let devices = global.get('cached_controller_devices') || [];
let relay = global.get('relay_state') || {};

// Devices arrive already sorted by display_order; sort defensively in case
// the cache was filled from somewhere else.
devices = devices.slice().sort((a, b) =>
    (a.display_order - b.display_order) || (a.deviceid - b.deviceid));

let boardsById = {};
(global.get('cached_boards_all') || []).forEach(b => { boardsById[b.id] = b; });
let zoneById = {};
(global.get('cached_zones') || []).forEach(z => { zoneById[z.id] = z.name; });

let cards = [];
devices.forEach(dev => {
    let board = boardsById[dev.board_id];
    let boardOffline = board ? board.status !== 'online' : false;
    let chans = [];
    try { chans = JSON.parse(dev.channels || '[]'); } catch (e) {}
    chans.forEach((c, i) => {
        if (!c.pin || c.enabled === false) return;
        let pin = parseInt(c.pin.toString().replace(/[^0-9]/g, ''));
        if (isNaN(pin)) return;
        cards.push({
            id: dev.deviceid + ':' + i,
            deviceid: dev.deviceid,
            zone_id: dev.zone_id || null,
            zone: dev.zone_id ? (zoneById[dev.zone_id] || 'Zone ' + dev.zone_id) : null,
            label: dev.name + ' - ' + (c.name || String(i + 1)),
            pin: pin,
            offline: boardOffline,
            state: relay[pin] === 'ON' ? 'ON' : 'OFF'
        });
    });
});

return [{ topic: 'controls', payload: cards }];

let p = msg.payload;
if (!p) return null;

// relay on/off -> straight out to MQTT
if (p.action === 'control') {
    return [{ payload: { pin: p.pin, state: p.state }, topic: 'esp32/control' }, null];
}

// ---- zones ----
if (p.action === 'add_zone') {
    let n = String(p.name || '').replace(/'/g, "''");
    return [null, [{ topic: "INSERT INTO `iot`.`tbl_zone` (`name`) VALUES ('" + n + "');" }]];
}
if (p.action === 'rename_zone') {
    let n = String(p.name || '').replace(/'/g, "''");
    return [null, [{ topic: "UPDATE `iot`.`tbl_zone` SET name='" + n + "' WHERE id=" + parseInt(p.id) + ";" }]];
}
if (p.action === 'set_zone') {
    let z = (p.zone_id === null || p.zone_id === undefined || isNaN(parseInt(p.zone_id)))
            ? 'NULL' : parseInt(p.zone_id);
    return [null, [{ topic: "UPDATE `iot`.`tbl_iotdevice` SET zone_id=" + z
                            + " WHERE deviceid=" + parseInt(p.deviceid) + ";" }]];
}

// the page sends its full order after a drag or an arrow press
if (p.action === 'set_order' && Array.isArray(p.ids)) {
    let sql = p.ids.map((id, i) =>
        ({ topic: "UPDATE `iot`.`tbl_iotdevice` SET display_order=" + i +
                  " WHERE deviceid=" + parseInt(id) + ";" }));
    return [null, sql];
}

// kept for compatibility: move one card relative to its neighbour
if (p.action === 'reorder') {
    let list = (p.kind === 'control'
        ? global.get('cached_controller_devices')
        : global.get('cached_sensor_devices')) || [];

    list = list.slice().sort((a, b) =>
        (a.display_order - b.display_order) || (a.deviceid - b.deviceid));

    let idx = list.findIndex(x => String(x.deviceid) === String(p.deviceid));
    if (idx < 0) return null;
    let swapIdx = p.dir === 'up' ? idx - 1 : idx + 1;
    if (swapIdx < 0 || swapIdx >= list.length) return null;   // already at the end

    let a = list[idx], b = list[swapIdx];

    // Rows can share an order value (they all default to 0), which would make
    // a swap a no-op. Write positions rather than swapping the stored numbers.
    let sql = [];
    list.forEach((dev, i) => {
        let order = i;
        if (i === idx) order = swapIdx;
        else if (i === swapIdx) order = idx;
        sql.push({ topic: "UPDATE `iot`.`tbl_iotdevice` SET display_order=" + order +
                          " WHERE deviceid=" + parseInt(dev.deviceid) + ";" });
    });
    return [null, sql];
}

return null;

const SENSOR_CATALOG = {
  'DHT22':[{key:'temperature',label:'Temperature',unit:'C',digits:1},{key:'humidity',label:'Humidity',unit:'%',digits:1}],
  'DHT11':[{key:'temperature',label:'Temperature',unit:'C',digits:1},{key:'humidity',label:'Humidity',unit:'%',digits:1}],
  'Soil Moisture Sensor':[{key:'soil_percent',label:'Soil Moisture',unit:'%',digits:0}],
  'PIR Motion Sensor':[{key:'motion',label:'Motion',unit:'',digits:0}],
  'LDR Photoresistor':[{key:'light_percent',label:'Light Level',unit:'%',digits:0}],
  'Water Flow Sensor':[{key:'flow_rate',label:'Water Flow',unit:'L/min',digits:1}]
};

// MACs arrive in different shapes depending on firmware version
// ("28:05:A5:34:9F:A0" vs "2805A5349FA0"). Compare on a normalised key.
function normMac(m) {
    return String(m == null ? '' : m).toUpperCase().replace(/[^0-9A-F]/g, '');
}
function normPin(p) {
    let n = parseInt(String(p == null ? '' : p).replace(/[^0-9]/g, ''));
    return isNaN(n) ? null : n;
}

// Readings are keyed MAC|PIN so two sensors of the SAME type on one board
// stay separate. Firmware that still sends only flat fields (no readings[])
// is stored under MAC|* and used as a fallback.
function keyFor(mac, pin) { return normMac(mac) + '|' + (pin === null ? '*' : pin); }

// Pull the metric values out of one reading object, whatever shape it is.
function extract(src) {
    let out = {};
    let temp = parseFloat(src.temperature !== undefined ? src.temperature : src.Temperature);
    let hum  = parseFloat(src.humidity !== undefined ? src.humidity : src.Humidity);

    let soil = parseInt(src.soil_percent);
    if (isNaN(soil)) {
        let raw = parseInt(src.Soil !== undefined ? src.Soil : src.soil_raw);
        if (!isNaN(raw)) soil = Math.max(0, Math.min(100, Math.round((1 - raw / 4095) * 100)));
    }

    let motion;
    if (src.motion !== undefined) {
        motion = (src.motion === true || src.motion === 1 || src.motion === '1' || src.motion === 'Detected') ? 1 : 0;
    }

    let light = parseInt(src.light_percent);
    if (isNaN(light)) {
        let raw = parseInt(src.LDR !== undefined ? src.LDR : src.light_raw);
        if (!isNaN(raw)) light = Math.max(0, Math.min(100, Math.round((raw / 4095) * 100)));
    }

    let flow = parseFloat(src.flow_rate);

    if (!isNaN(temp))  out.temperature  = temp;
    if (!isNaN(hum))   out.humidity     = hum;
    if (!isNaN(soil))  out.soil_percent = soil;
    if (motion !== undefined) out.motion = motion;
    if (!isNaN(light)) out.light_percent = light;
    if (!isNaN(flow))  out.flow_rate    = flow;
    return out;
}

let devices = global.get('cached_sensor_devices') || [];
let live = global.get('live_by_key') || {};

let dd = msg.payload;
if (typeof dd === 'string') { try { dd = JSON.parse(dd); } catch (e) { dd = null; } }

if (dd && typeof dd === 'object' && !Array.isArray(dd) && dd.device_id) {
    let mac = dd.device_id;

    if (Array.isArray(dd.readings)) {
        // Per-sensor payload: each entry tagged with the pin it came from.
        dd.readings.forEach(r => {
            let k = keyFor(mac, normPin(r.pin));
            live[k] = Object.assign({}, live[k], extract(r), { ts: Date.now() });
        });
    }
    // Always keep a board-wide entry too, so a device with a blank or
    // mismatched pin still resolves to something rather than showing nothing.
    let flat = extract(dd);
    if (Object.keys(flat).length) {
        let fk = keyFor(mac, null);
        live[fk] = Object.assign({}, live[fk], flat, { ts: Date.now() });
    }
    global.set('live_by_key', live);
}

// Board liveness, so a card can be greyed out rather than silently going stale.
let boardsById = {};
(global.get('cached_boards_all') || []).forEach(b => { boardsById[b.id] = b; });

let zoneById = {};
(global.get('cached_zones') || []).forEach(z => { zoneById[z.id] = z.name; });

let cards = [];

// Cards follow the order set on the Overview page (display_order), so a
// user-chosen layout survives a reload.
devices = devices.slice().sort((a, b) =>
    ((a.display_order || 0) - (b.display_order || 0)) || (a.deviceid - b.deviceid));

devices.forEach(dev => {
    let metrics = SENSOR_CATALOG[dev.sensors];
    if (!metrics) return;

    // Prefer the reading from this device's own pin; fall back to the
    // board-wide entry if the firmware isn't sending per-pin readings yet.
    let exact = live[keyFor(dev.mac_address, normPin(dev.pin))];
    let fallback = live[keyFor(dev.mac_address, null)];
    let vals = exact || fallback || {};

    // How old is this reading? A value that stops updating must LOOK stale,
    // otherwise a dead feed is indistinguishable from a live one.
    let ageSec = vals.ts ? Math.round((Date.now() - vals.ts) / 1000) : null;

    metrics.forEach(m => {
        let v = vals[m.key];
        let display = null;
        if (v !== undefined && v !== null) {
            if (m.key === 'motion') display = (v === 1 ? 'Detected' : 'Clear');
            else if (typeof v === 'number') display = v.toFixed(m.digits);
            else display = v;
        }
        let board = boardsById[dev.board_id];
        let boardOffline = board ? board.status !== 'online' : false;
        cards.push({
            id: dev.deviceid + ':' + m.key,
            deviceid: dev.deviceid,
            zone_id: dev.zone_id || null,
            zone: dev.zone_id ? (zoneById[dev.zone_id] || 'Zone ' + dev.zone_id) : null,
            label: dev.name + ' - ' + m.label,
            device: (dev.board_name || dev.name) + (dev.pin ? ' (pin ' + dev.pin + ')' : ''),
            value: display,
            unit: m.unit,
            ageSec: ageSec,
            offline: boardOffline,
            stale: ageSec === null ? false : ageSec > 30
        });
    });
});

return [{ topic: 'sensors', payload: cards }];

// Records the last commanded state per pin so the dashboard shows
// reality after a page reload, and reflects trigger/schedule actions.
let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return null; } }
if (!p || p.pin === undefined) return null;

let pin = parseInt(String(p.pin).replace(/[^0-9]/g, ''));
if (isNaN(pin)) return null;

let state = String(p.state || '').toUpperCase() === 'ON' ? 'ON' : 'OFF';
let relay = global.get('relay_state') || {};
relay[pin] = state;
global.set('relay_state', relay);

return msg;   // re-render the control cards immediately

msg.payload = (msg.payload||[]).map(function(d){
    return {
        deviceid: 'RAC'+(10000+parseInt(d.deviceid||0)),
        name: d.name,
        device_type: d.device_type||'sensor',
        sensors: d.sensors||'',
        controller: d.controller||'',
        pin: d.pin||'',
        channels: d.channels||''
    };
});
msg.topic = 'devices';
return msg;

let p = msg.payload;
if (!p || !p.cond_device || !p.act_device) return null;

function q(v){ return "'" + String(v == null ? '' : v).replace(/'/g, "''") + "'"; }
function num(v, dflt){ let n = parseInt(v); return isNaN(n) ? dflt : n; }
function nullableTime(v){ return v ? q(v) : 'NULL'; }

let condJson  = q(JSON.stringify(p.conditions || {}));
let actPin    = (p.act_pin === null || p.act_pin === undefined || isNaN(parseInt(p.act_pin)))
                  ? 'NULL' : parseInt(p.act_pin);
let enabled   = p.enabled ? 1 : 0;
let dur       = num(p.duration, 300);

if (p.id) {
    msg.topic = "UPDATE `iot`.`tbl_trigger` SET "
        + "`name`=" + q(p.name) + ", "
        + "`cond_device`=" + q(p.cond_device) + ", "
        + "`conditions`=" + condJson + ", "
        + "`act_device`=" + q(p.act_device) + ", "
        + "`act_controller`=" + q(p.act_controller) + ", "
        + "`act_pin`=" + actPin + ", "
        + "`action`=" + q(p.action || 'on') + ", "
        + "`enabled`=" + enabled + ", "
        + "`time_from`=" + nullableTime(p.time_from) + ", "
        + "`time_to`=" + nullableTime(p.time_to) + ", "
        + "`duration`=" + dur + ", "
        + "`duration_display`=" + q(p.duration_display)
        + " WHERE id=" + parseInt(p.id) + ";";
} else {
    msg.topic = "INSERT INTO `iot`.`tbl_trigger` "
        + "(`name`,`cond_device`,`conditions`,`act_device`,`act_controller`,`act_pin`,"
        + "`action`,`enabled`,`time_from`,`time_to`,`duration`,`duration_display`) VALUES ("
        + q(p.name) + ", "
        + q(p.cond_device) + ", "
        + condJson + ", "
        + q(p.act_device) + ", "
        + q(p.act_controller) + ", "
        + actPin + ", "
        + q(p.action || 'on') + ", "
        + enabled + ", "
        + nullableTime(p.time_from) + ", "
        + nullableTime(p.time_to) + ", "
        + dur + ", "
        + q(p.duration_display) + ");";
}
return msg;

msg.payload = 'Trigger added!';
msg.topic = 'Success';
node.send([msg, { topic: 'SELECT * FROM iot.tbl_trigger ORDER BY id DESC;' }]);

// Parse conditions JSON for display
msg.payload = (msg.payload||[]).map(function(t){
    let conds = [];
    try { conds = JSON.parse(t.conditions||'[]'); } catch(e){}
    t.conditions_parsed = conds;
    return t;
});
return msg;

let p = msg.payload || {};

if (p.action === 'delete') {
    msg.topic = 'DELETE FROM `iot`.`tbl_trigger` WHERE id=' + parseInt(p.item.id) + ';';
    return [msg, null];
}

if (p.action === 'toggle') {
    msg.topic = 'UPDATE `iot`.`tbl_trigger` SET `enabled`=' + (p.enabled ? 1 : 0)
              + ' WHERE id=' + parseInt(p.id) + ';';
    return [msg, null];
}

if (p.action === 'edit') {
    // straight back to the form, no database round-trip
    return [null, { topic: 'edit_trigger', payload: p.item }];
}

return null;

msg.payload='Trigger deleted!';
msg.topic='Deleted';
node.send([msg,{topic:'SELECT * FROM iot.tbl_trigger ORDER BY id DESC;'}]);

let action = msg.payload && msg.payload.action;
let device = msg.payload && msg.payload.device;
if (action === 'select') { flow.set('selected_device', device); return null; }
if (action === 'edit') {
    flow.set('selected_device', device);
    node.send([null, { payload: device, topic: 'fill_form' }]);
    return;
}
if (action === 'delete') {
    let numericId = parseInt((device.deviceid||'').toString().replace(/^RAC/i,'')) - 10000;
    msg.topic = 'DELETE FROM `iot`.`tbl_iotdevice` WHERE deviceid=' + numericId + ';';
    node.send([msg, null]);
    return;
}
return null;

msg.payload = 'Device deleted!';
msg.topic = 'Deleted';
node.send([msg, { topic: "SELECT concat('RAC', 10000 + d.deviceid) AS deviceid, d.name, d.device_type, d.sensors, d.controller, d.pin, d.channels, d.remark, d.board_id, b.name AS board_name FROM iot.tbl_iotdevice d LEFT JOIN iot.tbl_esp32_board b ON d.board_id=b.id ORDER BY d.device_type, d.name;" }]);

let action = msg.payload && msg.payload.action;

if (action === 'delete_ctrl_type') {
    let name = (msg.payload.name || '').replace(/'/g, "''");
    msg.topic = "DELETE FROM `iot`.`tbl_controller_type` WHERE `name`='" + name + "';";
    node.send([msg, null]);
    return;
}

if (action === 'add_ctrl_type') {
    let name = (msg.payload.name || '').replace(/'/g, "''");
    msg.topic = "INSERT IGNORE INTO `iot`.`tbl_controller_type` (`name`) VALUES ('" + name + "');";
    node.send([msg, null]);
    return;
}

if (action === 'save') {
    let d = msg.payload.data;
    let name       = (d.name       || '').replace(/'/g, "''");
    let sensors    = (d.sensors    || '').replace(/'/g, "''");
    let controller = (d.controller || '').replace(/'/g, "''");
    let pin        = (d.pin        || '').replace(/'/g, "''");
    let channels   = (d.channels   || '').replace(/'/g, "''");
    let remark     = (d.remark     || '').replace(/'/g, "''");
    let dtype      = d.device_type === 'controller' ? 'controller' : 'sensor';
    let boardId    = d.board_id ? parseInt(d.board_id) : null;
    let boardSql   = boardId ? boardId : 'NULL';

    if (d.deviceid && d.deviceid !== '') {
        let numericId = parseInt(d.deviceid.toString().replace(/^RAC/i, '')) - 10000;
        msg.topic = "UPDATE `iot`.`tbl_iotdevice` SET" +
            " `name`='"       + name       + "'," +
            " `device_type`='" + dtype      + "'," +
            " `sensors`='"    + sensors    + "'," +
            " `controller`='" + controller + "'," +
            " `pin`='"        + pin        + "'," +
            " `channels`='"   + channels   + "'," +
            " `board_id`="    + boardSql   + "," +
            " `remark`='"     + remark     + "'" +
            " WHERE deviceid=" + numericId + ";";
    } else {
        msg.topic = "INSERT INTO `iot`.`tbl_iotdevice` (`name`, `device_type`, `sensors`, `controller`, `pin`, `channels`, `board_id`, `remark`)" +
            " VALUES ('" + name + "', '" + dtype + "', '" + sensors + "', '" + controller + "', '" + pin + "', '" + channels + "', " + boardSql + ", '" + remark + "');";
    }
    node.send([null, msg]);
    return;
}

return null;

msg.payload = 'Device saved!';
msg.topic = 'Success';
node.send([msg, { topic: "SELECT concat('RAC', 10000 + d.deviceid) AS deviceid, d.name, d.device_type, d.sensors, d.controller, d.pin, d.channels, d.remark, d.board_id, b.name AS board_name FROM iot.tbl_iotdevice d LEFT JOIN iot.tbl_esp32_board b ON d.board_id=b.id ORDER BY d.device_type, d.name;" }]);

msg.payload = (msg.payload||[]).map(function(d){
    return {
        deviceid: 'RAC'+(10000+parseInt(d.deviceid||0)),
        name: d.name,
        device_type: d.device_type||'sensor',
        sensors: d.sensors||'',
        controller: d.controller||'',
        pin: d.pin||'',
        channels: d.channels||''
    };
});
msg.topic = 'devices';
return msg;

let d = msg.payload;
let dev = (d.deviceid||'').replace(/'/g,"''");
let ctrl = (d.controller||'').replace(/'/g,"''");
let act = (d.action||'on').replace(/'/g,"''");
let durDisp = (d.duration_display||'').replace(/'/g,"''");
let sensor = d.read_sensor ? 1 : 0;
let dur = parseInt(d.duration)||300;
let pin = (d.pin===null||d.pin===undefined||isNaN(parseInt(d.pin))) ? 'NULL' : parseInt(d.pin);

if(d.type==='onetime'){
