// Report an event to the notification engine. It lives on another tab and
// Node-RED cannot wire across tabs, so events go through global context and
// are drained on the notify tick.
function notifyEvent(kind, title, detail, deviceid) {
    let q = global.get('notify_events') || [];
    q.push({ kind: kind, title: title, detail: detail, deviceid: deviceid || null, ts: Date.now() });
    if (q.length > 50) q = q.slice(-50);     // never let this grow unbounded
    global.set('notify_events', q);
}

// Live sensor ingest + trigger evaluation.
//
// Readings are keyed MAC|PIN so two sensors of the same type on one board are
// evaluated independently. Each trigger is checked against the readings of ITS
// OWN cond_device.
//
// Condition shape (new):
//   { metric, mode, value, for_seconds }
//     numeric modes : 'above' | 'below'
//     motion  modes : 'detected' | 'sustained_on' | 'clear_for'
// Legacy shape { temperature: { operator:'>', value:'30' } } is converted on
// the fly, so old rows keep working.

function normMac(m) { return String(m == null ? '' : m).toUpperCase().replace(/[^0-9A-F]/g, ''); }
function normPin(p) { let n = parseInt(String(p == null ? '' : p).replace(/[^0-9]/g, '')); return isNaN(n) ? null : n; }
function keyFor(mac, pin) { return normMac(mac) + '|' + (pin === null ? '*' : pin); }

function extract(src) {
    let out = {};
    let temp = parseFloat(src.temperature !== undefined ? src.temperature : src.Temperature);
    let hum  = parseFloat(src.humidity !== undefined ? src.humidity : src.Humidity);
    let soil = parseInt(src.soil_percent);
    if (isNaN(soil)) { let raw = parseInt(src.Soil !== undefined ? src.Soil : src.soil_raw); if (!isNaN(raw)) soil = Math.max(0, Math.min(100, Math.round((1 - raw / 4095) * 100))); }
    let motion;
    if (src.motion !== undefined) motion = (src.motion === true || src.motion === 1 || src.motion === '1' || src.motion === 'Detected') ? 1 : 0;
    else if (src.PIR !== undefined) motion = (String(src.PIR).toLowerCase().indexOf('detect') > -1) ? 1 : 0;
    let light = parseInt(src.light_percent);
    if (isNaN(light)) { let raw = parseInt(src.LDR !== undefined ? src.LDR : src.light_raw); if (!isNaN(raw)) light = Math.max(0, Math.min(100, Math.round((raw / 4095) * 100))); }
    let flow = parseFloat(src.flow_rate);
    if (!isNaN(temp)) out.temperature = temp;
    if (!isNaN(hum)) out.humidity = hum;
    if (!isNaN(soil)) out.soil_percent = soil;
    if (motion !== undefined) out.motion = motion;
    if (!isNaN(light)) out.light_percent = light;
    if (!isNaN(flow)) out.flow_rate = flow;
    return out;
}

// ---------- ingest ----------
let d = msg.payload;
if (typeof d === 'string') { try { d = JSON.parse(d); } catch (e) { return null; } }
if (!d || typeof d !== 'object') return null;

let live = global.get('live_by_key') || {};

if (d.device_id) {
    let mac = d.device_id;
    if (Array.isArray(d.readings)) {
        d.readings.forEach(r => {
            let k = keyFor(mac, normPin(r.pin));
            live[k] = Object.assign({}, live[k], extract(r), { ts: Date.now() });
        });
    }
    let flat = extract(d);
    if (Object.keys(flat).length) {
        let fk = keyFor(mac, null);
        live[fk] = Object.assign({}, live[fk], flat, { ts: Date.now() });
    }
    global.set('live_by_key', live);
}

// ---------- resolve devices ----------
let sensorDevices = global.get('cached_sensor_devices') || [];

// The dashboard stores a device as 'RAC10008' but the cache holds the raw
// id 8, so a plain string compare never matches. Normalise both to the
// numeric id before looking anything up.
function devKey(v) {
    let s = String(v == null ? '' : v).trim();
    let m = s.match(/^RAC(\d+)$/i);
    if (m) return String(parseInt(m[1], 10) - 10000);
    let n = parseInt(s, 10);
    return isNaN(n) ? s : String(n);
}

let devById = {};
sensorDevices.forEach(dev => { devById[devKey(dev.deviceid)] = dev; });

function stateForDevice(deviceid) {
    let dev = devById[devKey(deviceid)];
    if (!dev) return null;
    return live[keyFor(dev.mac_address, normPin(dev.pin))]
        || live[keyFor(dev.mac_address, null)]
        || null;
}

// ---------- condition helpers ----------
// Three stored shapes are understood, so nothing has to be migrated:
//   new     { match:'all'|'any', conditions:[ {device,metric,mode,value}, ... ] }
//   single  { metric, mode, value, for_seconds }
//   legacy  { temperature: { operator:'>', value:'30' } }
// Everything is normalised to the new shape before evaluation.
function parseCond(raw, t) {
    let c;
    try { c = JSON.parse(raw); } catch (e) { return null; }
    if (!c) return null;

    if (Array.isArray(c.conditions)) {
        return {
            match: c.match === 'any' ? 'any' : 'all',
            for_seconds: parseInt(c.for_seconds) || 0,
            list: c.conditions.map(x => ({
                device: x.device || t.cond_device,
                metric: x.metric, mode: x.mode,
                value: parseFloat(x.value)
            }))
        };
    }

    if (c.metric) {
        return {
            match: 'all', for_seconds: parseInt(c.for_seconds) || 0,
            list: [{ device: t.cond_device, metric: c.metric, mode: c.mode, value: parseFloat(c.value) }]
        };
    }

    let k = Object.keys(c)[0];
    if (!k) return null;
    let o = c[k];
    return {
        match: 'all', for_seconds: 0,
        list: [{
            device: t.cond_device, metric: k,
            mode: (o.operator === '<' || o.operator === '<=') ? 'below' : 'above',
            value: parseFloat(o.value)
        }]
    };
}

// Is one condition true right now?
function condTrue(c, stateFor) {
    let st = stateFor(c.device);
    if (!st) return null;                 // no data -> unknown
    let v = st[c.metric];
    if (v === undefined) return null;
    if (c.metric === 'motion') {
        return c.mode === 'clear_for' ? (v === 0) : (v === 1);
    }
    return c.mode === 'below' ? (v < c.value) : (v > c.value);
}

// Is `now` inside the trigger's active window? Handles windows that wrap
// past midnight, e.g. 22:00 -> 06:00.
function inWindow(t, now) {
    if (!t.time_from || !t.time_to) return true;
    const toMin = v => {
        const p = String(v).split(':');
        return parseInt(p[0]) * 60 + parseInt(p[1] || 0);
    };
    const from = toMin(t.time_from), to = toMin(t.time_to);
    const cur = now.getHours() * 60 + now.getMinutes();
    return from <= to ? (cur >= from && cur <= to) : (cur >= from || cur <= to);
}

// ---------- evaluate ----------
let triggers = flow.get('cached_triggers') || [];
let cooldowns = flow.get('trigger_cooldowns') || {};
let held = flow.get('trigger_held_since') || {};   // when each condition first became true
let now = new Date();
let nowMs = Date.now();
let toSend = [];

for (const t of triggers) {
    if (t.enabled !== undefined && !t.enabled) { delete held[t.id]; continue; }

    let c = parseCond(t.conditions, t);
    if (!c || !c.list.length) continue;

    let results = c.list.map(x => condTrue(x, stateForDevice));

    // A condition with no reading yet is unknown, not false. With ALL that
    // means "can't say yet" so the rule holds off; with ANY the others can
    // still satisfy it on their own.
    if (c.match === 'all' && results.some(r => r === null)) continue;
    if (c.match === 'any' && results.every(r => r === null)) continue;

    let raw = c.match === 'any'
        ? results.some(r => r === true)
        : results.every(r => r === true);

    // Sustained conditions must stay true for for_seconds before they count.
    let needSec = parseInt(c.for_seconds) || 0;
    let satisfied;
    if (needSec > 0) {
        if (raw) {
            if (!held[t.id]) held[t.id] = nowMs;
            satisfied = (nowMs - held[t.id]) >= needSec * 1000;
        } else {
            delete held[t.id];
            satisfied = false;
        }
    } else {
        satisfied = raw;
    }

    if (satisfied && !inWindow(t, now)) satisfied = false;

    let already = cooldowns[t.id];
    if (satisfied && !already) {
        cooldowns[t.id] = true;
        let onAction  = t.action === 'off' ? 'OFF' : 'ON';
        let offAction = onAction === 'ON' ? 'OFF' : 'ON';
        let onMsg  = t.act_pin ? { pin: t.act_pin, state: onAction }  : { device: t.act_controller, state: onAction };
        let offMsg = t.act_pin ? { pin: t.act_pin, state: offAction } : { device: t.act_controller, state: offAction };
        toSend.push({ payload: onMsg, topic: 'esp32/control' });
        notifyEvent('trigger_fired',
            'Trigger fired: ' + (t.name || ('#' + t.id)),
            'Turned ' + (t.act_controller || 'output')
                + (t.act_pin ? ' pin ' + t.act_pin : '') + ' ' + onAction
                + ' for ' + (t.duration_display || ((t.duration || 300) + ' sec')),
            t.cond_device);

        let durMs = (parseInt(t.duration) || 300) * 1000;
        setTimeout(() => {
            node.send({ payload: offMsg, topic: 'esp32/control' });
            let cd = flow.get('trigger_cooldowns') || {};
            delete cd[t.id];
            flow.set('trigger_cooldowns', cd);
            let h = flow.get('trigger_held_since') || {};
            delete h[t.id];
            flow.set('trigger_held_since', h);
        }, durMs);
    } else if (!satisfied && already) {
        delete cooldowns[t.id];
    }
}

flow.set('trigger_cooldowns', cooldowns);
flow.set('trigger_held_since', held);

if (toSend.length) return [toSend];
return null;

