// MySQL DATE/TIME columns can come back as JS Date objects OR strings
// depending on driver settings - normalize both cases safely.
function toDateStr(v) {
    if (!v) return '';
    if (v instanceof Date) {
        return v.getFullYear() + '-' + pad(v.getMonth() + 1) + '-' + pad(v.getDate());
    }
    return v.toString().slice(0, 10);
}
function toTimeStr(v) {
    if (!v) return '';
    if (v instanceof Date) {
        return pad(v.getHours()) + ':' + pad(v.getMinutes());
    }
    return v.toString().slice(0, 5);
}

let controlMsgs = [];
let dbMsgs = [];
let cooldowns = flow.get('sched_cooldowns') || {};

function fire(uniqueKey, controller, action, durationSec, pin) {
    if (cooldowns[uniqueKey]) return;
    cooldowns[uniqueKey] = true;
    let onAction = action === 'off' ? 'OFF' : 'ON';
    let offAction = onAction === 'ON' ? 'OFF' : 'ON';
    // Channel-targeted schedule (pin set) controls one relay pin directly,
    // same message shape the Overview control cards already use.
    let onMsg = pin ? { pin: pin, state: onAction } : { device: controller, state: onAction };
    let offMsg = pin ? { pin: pin, state: offAction } : { device: controller, state: offAction };
    controlMsgs.push({ payload: onMsg, topic: 'esp32/control' });
    notifyEvent('schedule_fired',
        'Schedule ran' + (controller ? ': ' + controller : ''),
        'Turned ' + (pin ? 'pin ' + pin : (controller || 'output')) + ' ' + onAction
            + ' for ' + Math.round((parseInt(durationSec) || 300) / 60) + ' min');
