// day_of_week is stored as a comma-joined list ("Monday, Wednesday"), so an
// exact match would never fire a multi-day schedule. Match on membership.
function runsToday(dayField, today) {
    if (!dayField) return false;
    return dayField.toString().split(',').map(x => x.trim()).indexOf(today) !== -1;
}

(flow.get('cached_repeat') || []).forEach(s => {
    let t = toTimeStr(s.time);
    if (runsToday(s.day_of_week, dow) && t === nowHM) {
        fire('repeat-' + s.id + '-' + dateStr + '-' + nowHM, s.controller, s.action, s.duration, s.pin);
    }
});

