    if (!keys.length) {
        node.warn('Rule "' + (rule.name || rule.id) + '" has no recipients');
        return null;
    }

    // Show live readings where the real alert would, so the test also
    // confirms the sensor data is reaching this page.
    const LABELS = {
        temperature:{l:'Temperature',u:'C'}, humidity:{l:'Humidity',u:'%'},
        soil_percent:{l:'Soil Moisture',u:'%'}, light_percent:{l:'Light',u:'%'},
        flow_rate:{l:'Water Flow',u:'L/min'}, motion:{l:'Motion',u:''}
    };
    function normMac(m){ return String(m == null ? '' : m).toUpperCase().replace(/[^0-9A-F]/g,''); }
    function normPin(p){ let n = parseInt(String(p == null ? '' : p).replace(/[^0-9]/g,'')); return isNaN(n) ? null : n; }

    let live = global.get('live_by_key') || {};
    let lines = [];
    (global.get('cached_sensor_devices') || []).forEach(s => {
        let r = live[normMac(s.mac_address) + '|' + normPin(s.pin)]
             || live[normMac(s.mac_address) + '|*'] || {};
        let parts = [];
        Object.keys(LABELS).forEach(k => {
            if (r[k] === undefined) return;
            let meta = LABELS[k];
            let v = (k === 'motion') ? (r[k] === 1 ? 'Detected' : 'Clear')
                                     : (typeof r[k] === 'number' ? r[k].toFixed(1) : r[k]) + meta.u;
            parts.push(meta.l + ': ' + v);
        });
        if (parts.length) lines.push(s.name + ' - ' + parts.join(' | '));
    });

    let text = '[TEST] ' + (rule.name || ('Rule ' + rule.id)) + '\n'
             + 'This is a test. The real alert fires when: ' + describeKind(rule) + '\n'
             + (lines.length ? lines.join('\n') : 'No sensor readings yet')
             + '\n' + new Date().toLocaleString();

    return [null, keys.map(k => ({ payload: {
        rule_id: rule.id, rule_name: '[test] ' + (rule.name || ('Rule ' + rule.id)),
        severity: rule.severity, recipient: k,
        subject: 'Smart Farm test: ' + (rule.name || 'alert'),
        text: text
    }}))];
}

function describeKind(r){
    if (r.kind === 'board_offline')   return 'a board goes quiet for ' + Math.round((r.offline_seconds||300)/60) + ' min';
    if (r.kind === 'trigger_fired')   return 'a trigger fires';
    if (r.kind === 'schedule_fired')  return 'a schedule runs';
    if (r.kind === 'interval_report') return 'every ' + Math.round((r.interval_seconds||21600)/3600) + ' h';
    return (r.metric || 'a reading') + ' goes ' + (r.mode === 'below' ? 'below ' : 'above ') + r.value;
}

// ---- test send: straight to the send path, no rule involved ----
if (p.action === 'test_recipient') {
    return [null, {
        payload: {
            rule_id: null, rule_name: 'Test message', severity: 'info',
            recipient: p.recipient,
            subject: 'Smart Farm test',
            text: 'Test message from Smart Farm. If you can read this, notifications are working.'
        }
    }];
}

// ---- rules ----
if (p.action === 'save_rule') {
    let cols = {
        name: q(p.name), kind: q(p.kind), enabled: p.enabled ? 1 : 0,
        severity: q(p.severity),
        cond_device: q(p.cond_device), metric: q(p.metric), mode: q(p.mode),
        value: dbl(p.value), value2: dbl(p.value2),
        for_seconds: num(p.for_seconds, 0),
        offline_seconds: num(p.offline_seconds, 300),
        interval_seconds: num(p.interval_seconds, 21600),
        cooldown_seconds: num(p.cooldown_seconds, 1800),
        repeat_seconds: num(p.repeat_seconds, 0),
        send_recovery: p.send_recovery ? 1 : 0,
        quiet_from: tm(p.quiet_from), quiet_to: tm(p.quiet_to),
        recipients: q(JSON.stringify(p.recipients || []))
    };
    let keys = Object.keys(cols);
    if (p.id) {
        msg.topic = "UPDATE `iot`.`tbl_notify_rule` SET "
            + keys.map(k => "`" + k + "`=" + cols[k]).join(",")
            + " WHERE id=" + num(p.id, 0) + ";";
    } else {
        msg.topic = "INSERT INTO `iot`.`tbl_notify_rule` ("
            + keys.map(k => "`" + k + "`").join(",") + ") VALUES ("
            + keys.map(k => cols[k]).join(",") + ");";
    }
    return [msg, null];
}
if (p.action === 'del_rule') {
    msg.topic = "DELETE FROM `iot`.`tbl_notify_rule` WHERE id=" + num(p.id, 0) + ";";
    return [msg, null];
}
if (p.action === 'toggle_rule') {
    msg.topic = "UPDATE `iot`.`tbl_notify_rule` SET enabled=" + (p.enabled ? 1 : 0)
              + " WHERE id=" + num(p.id, 0) + ";";
    return [msg, null];
}

// ---- settings ----
if (p.action === 'save_settings') {
    let out = [];
    ['notify_url','notify_token'].forEach(k => {
        if (p[k] === undefined) return;
        out.push({ topic: "INSERT INTO `iot`.`tbl_setting` (skey,svalue) VALUES ("
            + q(k) + "," + q(p[k]) + ") ON DUPLICATE KEY UPDATE svalue=VALUES(svalue);" });
    });
    return [out, null];
}

return null;

// Expects msg.payload = { recipient, subject, text, severity, rule_id, rule_name }
let p = msg.payload || {};
if (!p.recipient) return null;

let cfg = global.get('notify_settings') || {};
let base = (cfg.notify_url || '').replace(/\/+$/, '');
if (!base) {
    node.warn('notify_url is not set - open the Notifications page and set the service URL');
    return null;
}

return {
    method: 'POST',
    url: base + '/notify/send',
    headers: {
        'content-type': 'application/x-www-form-urlencoded',
        'Authorization': 'Bearer ' + (cfg.notify_token || '')
    },
    payload: {
        recipient: p.recipient,
        message: p.text || '',
        subject: p.subject || ('Smart Farm: ' + (p.rule_name || 'alert'))
    },
    _meta: {
        rule_id: p.rule_id || null,
        rule_name: p.rule_name || '',
        recipient: p.recipient,
        severity: p.severity || 'info',
        text: p.text || ''
    }
};

let m = msg._meta || {};
let code = msg.statusCode;
let ok = (code >= 200 && code < 300);

// The service waits for Telegram/SMTP before replying, so a non-2xx here is a
// real delivery failure, not just a rejected hand-off. Surface the reason.
let detail = '';
if (!ok) {
    try {
        detail = typeof msg.payload === 'string' ? msg.payload : JSON.stringify(msg.payload);
    } catch (e) { detail = String(msg.payload); }
    node.warn('Notify failed (' + code + '): ' + detail.slice(0, 300));
}

function q(v){ return "'" + String(v == null ? '' : v).replace(/'/g, "''").slice(0, 900) + "'"; }
msg.topic = "INSERT INTO `iot`.`tbl_notify_log` "
    + "(`rule_id`,`rule_name`,`channel`,`target`,`severity`,`message`,`status`) VALUES ("
    + (m.rule_id ? parseInt(m.rule_id) : 'NULL') + ","
    + q(m.rule_name) + "," + q('service') + "," + q(m.recipient) + ","
    + q(m.severity) + "," + q(ok ? m.text : (m.text + ' [' + detail.slice(0,200) + ']')) + ","
    + q(ok ? 'sent' : 'failed') + ");";
return msg;

// ===================== Notification engine =====================
// Two jobs:
//   1. absorb sensor readings (same keying as the trigger engine: MAC|PIN)
//   2. on each tick, evaluate every rule and emit messages to send
//
// Anti-spam is the whole point here. A relay firing twice is harmless; a
// phone buzzing every 5 seconds is not. Every alert passes cooldown, quiet
// hours and hold-time checks before it is allowed out.

function normMac(m){ return String(m == null ? '' : m).toUpperCase().replace(/[^0-9A-F]/g,''); }
function normPin(p){ let n = parseInt(String(p == null ? '' : p).replace(/[^0-9]/g,'')); return isNaN(n) ? null : n; }
function keyFor(mac, pin){ return normMac(mac) + '|' + (pin === null ? '*' : pin); }
function devKey(v){
    let s = String(v == null ? '' : v).trim();
    let m = s.match(/^RAC(\d+)$/i);
    if (m) return String(parseInt(m[1],10) - 10000);
    let n = parseInt(s,10);
    return isNaN(n) ? s : String(n);
}

const LABELS = {
    temperature:{l:'Temperature',u:'C'}, humidity:{l:'Humidity',u:'%'},
    soil_percent:{l:'Soil Moisture',u:'%'}, light_percent:{l:'Light',u:'%'},
    flow_rate:{l:'Water Flow',u:'L/min'}, motion:{l:'Motion',u:''}
};

function extract(src){
    let out = {};
    let t = parseFloat(src.temperature !== undefined ? src.temperature : src.Temperature);
    let h = parseFloat(src.humidity !== undefined ? src.humidity : src.Humidity);
    let s = parseInt(src.soil_percent);
    let l = parseInt(src.light_percent);
    let fr = parseFloat(src.flow_rate);
    let mo;
    if (src.motion !== undefined) mo = (src.motion === true || src.motion === 1 || src.motion === '1' || src.motion === 'Detected') ? 1 : 0;
    if (!isNaN(t)) out.temperature = t;
    if (!isNaN(h)) out.humidity = h;
    if (!isNaN(s)) out.soil_percent = s;
    if (!isNaN(l)) out.light_percent = l;
    if (!isNaN(fr)) out.flow_rate = fr;
    if (mo !== undefined) out.motion = mo;
    return out;
}

// ---------- 1. ingest ----------
let inp = msg.payload;
if (typeof inp === 'string') { try { inp = JSON.parse(inp); } catch(e) { inp = null; } }
if (inp && typeof inp === 'object' && !Array.isArray(inp) && inp.device_id) {
    let live = global.get('live_by_key') || {};
    let mac = inp.device_id;
    if (Array.isArray(inp.readings)) {
        inp.readings.forEach(r => {
            let k = keyFor(mac, normPin(r.pin));
            live[k] = Object.assign({}, live[k], extract(r), { ts: Date.now() });
        });
    }
    let flat = extract(inp);
    if (Object.keys(flat).length) {
        let fk = keyFor(mac, null);
        live[fk] = Object.assign({}, live[fk], flat, { ts: Date.now() });
    }
    global.set('live_by_key', live);
    return null;              // readings never trigger evaluation directly
}

// ---------- 2. evaluate (tick only) ----------
let rules    = global.get('cached_notify_rules') || [];
let sensors  = global.get('cached_sensor_devices') || [];
let boards   = global.get('cached_boards_all') || [];
let live     = global.get('live_by_key') || {};
let state    = flow.get('notify_state') || {};
let now = Date.now();
let d = new Date();
let out = [];

let sensorById = {};
sensors.forEach(s => { sensorById[devKey(s.deviceid)] = s; });

function readingsFor(dev){
    if (!dev) return {};
    return live[keyFor(dev.mac_address, normPin(dev.pin))]
        || live[keyFor(dev.mac_address, null)] || {};
}

function fmt(metric, v){
    let meta = LABELS[metric] || { l: metric, u: '' };
    if (v === undefined || v === null) return meta.l + ': --';
    if (metric === 'motion') return meta.l + ': ' + (v === 1 ? 'Detected' : 'Clear');
    return meta.l + ': ' + (typeof v === 'number' ? v.toFixed(1) : v) + meta.u;
}

function snapshot(dev){
    let r = readingsFor(dev);
    let parts = [];
    Object.keys(LABELS).forEach(k => { if (r[k] !== undefined) parts.push(fmt(k, r[k])); });
    return parts.join(' | ') || 'no readings yet';
}

function inQuiet(rule){
    if (!rule.quiet_from || !rule.quiet_to) return false;
    const toMin = v => { let p = String(v).split(':'); return parseInt(p[0])*60 + parseInt(p[1]||0); };
    let f = toMin(rule.quiet_from), t = toMin(rule.quiet_to);
    let cur = d.getHours()*60 + d.getMinutes();
    return f <= t ? (cur >= f && cur <= t) : (cur >= f || cur <= t);
}

// The single gate every outgoing message passes through.
function emit(rule, text, opts){
    opts = opts || {};
    let st = state[rule.id] = state[rule.id] || {};

    // critical alerts ignore quiet hours; everything else waits
    if (!opts.force && rule.severity !== 'critical' && inQuiet(rule)) return;

    let cooldown = (parseInt(rule.cooldown_seconds) || 0) * 1000;
    if (!opts.ignoreCooldown && st.lastSent && (now - st.lastSent) < cooldown) return;

    let keys = rule.recips || [];
    if (!keys.length) return;

    keys.forEach(k => {
        out.push({ payload: {
            rule_id: rule.id, rule_name: rule.name || ('Rule ' + rule.id),
            severity: rule.severity, recipient: k,
            subject: 'Smart Farm: ' + (rule.name || 'alert'),
            text: text
        }});
    });
    st.lastSent = now;
}

const ICON = { info: 'i', warning: '!', critical: '!!' };

rules.forEach(rule => {
    if (!rule.enabled) { delete state[rule.id]; return; }
    let st = state[rule.id] = state[rule.id] || {};
    let tag = '[' + (ICON[rule.severity] || 'i') + '] ';

    // ---------------- threshold ----------------
    if (rule.kind === 'threshold') {
        let dev = sensorById[devKey(rule.cond_device)];
        if (!dev) return;
        let r = readingsFor(dev);
        let v = r[rule.metric];
        if (v === undefined) return;

        let meta = LABELS[rule.metric] || { l: rule.metric, u: '' };
        let alertAt = parseFloat(rule.value);
        // Deadband: recover at a value INSIDE the safe zone, otherwise a
        // reading sitting on the threshold alarms and clears repeatedly.
        let clearAt = (rule.value2 === null || rule.value2 === undefined || isNaN(parseFloat(rule.value2)))
                      ? alertAt : parseFloat(rule.value2);
        let bad = rule.mode === 'below' ? (v < alertAt) : (v > alertAt);
        let good = rule.mode === 'below' ? (v > clearAt) : (v < clearAt);

        let need = (parseInt(rule.for_seconds) || 0) * 1000;
        if (bad) {
            if (!st.badSince) st.badSince = now;
        } else {
            st.badSince = null;
        }
        let held = st.badSince && (now - st.badSince) >= need;

        if (held && !st.active) {
            st.active = true;
            st.activeSince = now;
            emit(rule, tag + (rule.name || 'Alert') + '\n'
                + dev.name + ' ' + meta.l + ' is ' + v + meta.u
                + ' (limit ' + alertAt + meta.u + ')\n'
                + snapshot(dev) + '\n'
                + (dev.board_name || '') + ' ' + d.toLocaleTimeString());
        } else if (st.active && good) {
            st.active = false;
            if (rule.send_recovery) {
                let mins = st.activeSince ? Math.round((now - st.activeSince)/60000) : 0;
                emit(rule, '[ok] ' + (rule.name || 'Alert') + ' cleared\n'
                    + dev.name + ' ' + meta.l + ' back to ' + v + meta.u
                    + (mins ? ' after ' + mins + ' min' : '') + '\n'
                    + snapshot(dev), { ignoreCooldown: true });
            }
            st.activeSince = null;
        } else if (st.active && rule.repeat_seconds > 0) {
            // still wrong: remind, but no more often than repeat_seconds
            if (!st.lastSent || (now - st.lastSent) >= rule.repeat_seconds * 1000) {
                let mins = st.activeSince ? Math.round((now - st.activeSince)/60000) : 0;
                emit(rule, tag + 'STILL ' + (rule.name || 'alert') + ' (' + mins + ' min)\n'
                    + dev.name + ' ' + meta.l + ' is ' + v + meta.u + '\n'
                    + snapshot(dev), { ignoreCooldown: true });
            }
        }
        return;
    }

    // ---------------- board offline ----------------
    // A dead board never crosses a threshold, so a normal rule can never
    // catch it. This is the one alert that fires on the ABSENCE of data.
    if (rule.kind === 'board_offline') {
        let limit = (parseInt(rule.offline_seconds) || 300) * 1000;
        boards.forEach(b => {
            if (!b.name) return;                       // unregistered
            if (rule.cond_device && String(rule.cond_device) !== String(b.id)) return;
            // seen_ms is set by the boards renderer from live announces —
            // parsing b.last_seen would reintroduce the timezone problem.
            let seen = b.seen_ms || 0;
            let gone = !seen || (now - seen) > limit;
            let key = 'b' + b.id;
            st[key] = st[key] || {};
            if (gone && !st[key].active) {
                st[key].active = true;
                let mins = seen ? Math.round((now - seen)/60000) : null;
                emit(rule, tag + 'Board offline: ' + b.name + '\n'
                    + (mins !== null ? 'No data for ' + mins + ' min' : 'Never reported')
                    + '\nLast IP ' + (b.last_ip || '?'), { ignoreCooldown: true });
            } else if (!gone && st[key].active) {
                st[key].active = false;
                if (rule.send_recovery) {
                    emit(rule, '[ok] Board back online: ' + b.name, { ignoreCooldown: true });
                }
            }
        });
        return;
    }

    // ---------------- periodic status report ----------------
    if (rule.kind === 'interval_report') {
        let every = (parseInt(rule.interval_seconds) || 21600) * 1000;
        if (st.lastReport && (now - st.lastReport) < every) return;
        st.lastReport = now;

        let lines = [];
        let wanted = rule.cond_device
            ? sensors.filter(s => devKey(s.deviceid) === devKey(rule.cond_device))
            : sensors;
        wanted.forEach(s => { lines.push(s.name + ' - ' + snapshot(s)); });

        let offline = boards.filter(b => b.name && b.status !== 'online').map(b => b.name);
        emit(rule, '[i] ' + (rule.name || 'Status report') + '\n'
            + d.toLocaleString() + '\n'
            + (lines.length ? lines.join('\n') : 'No sensors registered')
            + (offline.length ? '\nOffline boards: ' + offline.join(', ') : ''),
            { ignoreCooldown: true, force: true });
        return;
    }
});

// ---------------- events from the trigger / schedule engines ----------------
// Those run on another tab and Node-RED cannot wire across tabs, so they
// leave events in global context and this drains them.
let events = global.get('notify_events') || [];
if (events.length) {
    global.set('notify_events', []);
    events.forEach(ev => {
        rules.forEach(rule => {
            if (!rule.enabled) return;
            if (rule.kind !== ev.kind) return;      // 'trigger_fired' | 'schedule_fired'

            // Report only what the event was about. A trigger names the sensor
            // whose reading caused it, so that one reading is relevant; a
            // schedule fires on a clock and has no sensor, so it gets nothing.
            // Dumping every sensor here buries the actual news — that belongs
            // in the status report instead.
            let dev = ev.deviceid ? sensorById[devKey(ev.deviceid)] : null;
            let extra = dev ? '\n' + snapshot(dev) : '';

            emit(rule, '[' + (ICON[rule.severity] || 'i') + '] ' + ev.title + '\n'
                + ev.detail + extra + '\n' + d.toLocaleTimeString());
        });
    });
}

flow.set('notify_state', state);
return [out];

let cfg = msg.payload || {};
let base = (cfg.notify_url || '').replace(/\/+$/, '');
if (!base) return null;
return {
    method: 'GET',
    url: base + '/notify/recipients',
    headers: { 'Authorization': 'Bearer ' + (cfg.notify_token || '') }
};

// Recipients are defined in the Python service config, so chat ids and email
// addresses never reach the dashboard or the exported flow. We only ever see
// a key and a label.
let cfg = global.get('notify_settings') || {};
let url = (cfg.notify_url || '(not set)');
let code = msg.statusCode;
let list = [];
let status = '';

if (code === undefined) {
    // no HTTP response at all: wrong host, wrong port, or nothing listening
    status = 'Could not reach the notify service at ' + url
           + ' — is it running, and is the URL right for a container?';
} else if (code === 401 || code === 403) {
    status = 'Service reachable at ' + url + ' but rejected the token (HTTP ' + code + ').';
} else if (code < 200 || code >= 300) {
    status = 'Service at ' + url + ' returned HTTP ' + code + '.';
} else {
    list = (msg.payload && msg.payload.recipients) || [];
    if (!Array.isArray(list)) list = [];
    if (!list.length) {
        status = 'Connected, but the service reports no recipients — check RECIPIENTS '
               + 'in /etc/smartfarm-notify.env, then restart the service.';
    } else {
        status = 'Connected — ' + list.length + ' recipient(s).';
    }
}

global.set('notify_recipients', list);
global.set('notify_status', status);

return [
    { topic: 'recipients', payload: list },
    { topic: 'notify_status', payload: { ok: list.length > 0, text: status } }
];
